insert into public.role_foundations
(id,role_family,canonical_role,version,title,summary,knowledge_content,competency_tags,methodology_tags,qa_rules,risk_classification,source_ids,freshness_class,acquired_at,last_verified_at,next_review_at,status)
values
('30000000-0000-0000-0000-000000000001','design',null,'1','Designer Professional Foundation v1','Reusable professional foundation for graphic, UI/UX, product and brand design.',
 jsonb_build_array(
 jsonb_build_object('topic','Visual hierarchy and composition','summary','Use size, weight, contrast, spacing, alignment and placement to communicate priority and create a coherent reading path.','professional_rules',jsonb_build_array('Primary information must visually dominate secondary information','Avoid competing focal points','Use proximity and repetition to reveal relationships','Use whitespace deliberately rather than filling every area'),'source_ids',jsonb_build_array('10000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000004')),
 jsonb_build_object('topic','Layout and spacing','summary','Use grids, safe margins, gutters, internal padding and a repeatable spacing rhythm to maintain clarity across formats.','professional_rules',jsonb_build_array('Keep text and critical marks away from trim and viewport edges','Preserve logo clear space','Avoid overcrowding and edge-hugging text','Adapt density and composition responsively'),'source_ids',jsonb_build_array('10000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000004')),
 jsonb_build_object('topic','Typography and readability','summary','Typography should establish hierarchy while preserving legibility, scannability and consistent rhythm.','professional_rules',jsonb_build_array('Use a limited intentional type scale','Maintain readable line length and spacing','Do not sacrifice legibility for decoration','Treat contrast and text size as accessibility concerns'),'source_ids',jsonb_build_array('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002')),
 jsonb_build_object('topic','UI/UX and accessibility','summary','Design interfaces around clear information architecture, predictable interaction, usability, responsive behavior and accessible perceivability.','professional_rules',jsonb_build_array('Navigation and CTAs need clear hierarchy','Interactive patterns should remain consistent','Check readable contrast and focus/interaction states','Design for multiple viewport sizes and input modes'),'source_ids',jsonb_build_array('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003')),
 jsonb_build_object('topic','Landing pages and hero sections','summary','A hero should communicate the primary value quickly with disciplined density, headline hierarchy and a prominent next action.','professional_rules',jsonb_build_array('Respect fold awareness without cramming content','Make supporting copy subordinate to the headline','Give primary CTA stronger emphasis than secondary actions','Preserve responsive composition'),'source_ids',jsonb_build_array('10000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000004')),
 jsonb_build_object('topic','Business cards, banners and brand work','summary','Small-format and promotional assets require safe areas, accurate identity, readable contact information and balanced whitespace.','professional_rules',jsonb_build_array('Use approved company identity only','Never invent contact data','Maintain print/digital margin awareness','Do not distort or redraw official logos when an asset is supplied'),'source_ids',jsonb_build_array('10000000-0000-0000-0000-000000000002')),
 jsonb_build_object('topic','Dashboards and product UI','summary','Data-heavy interfaces need coherent spacing, semantic grouping, consistent cards/components and readable density.','professional_rules',jsonb_build_array('Group related KPIs semantically','Use consistent component hierarchy','Do not over-encode with decoration','Choose density appropriate to the decision task'),'source_ids',jsonb_build_array('10000000-0000-0000-0000-000000000004'))),
 array['hierarchy','composition','typography','color','accessibility','responsive-design','branding','dashboard-ui'],array['grid','spacing-system','usability-review','accessibility-review','visual-qa'],
 '["text too close to edge","insufficient margin","poor contrast","malformed logo","inconsistent branding","clutter","poor hierarchy","incorrect company facts","invented data"]','standard',
 array['10000000-0000-0000-0000-000000000001'::uuid,'10000000-0000-0000-0000-000000000002'::uuid,'10000000-0000-0000-0000-000000000003'::uuid,'10000000-0000-0000-0000-000000000004'::uuid],
 'slow_changing',now(),now(),now()+interval '180 days','active'),
('30000000-0000-0000-0000-000000000002','marketing',null,'1','Marketing Specialist Professional Foundation v1','Reusable marketing foundation for strategy, acquisition and lifecycle work.',
 jsonb_build_array(
 jsonb_build_object('topic','Market and positioning','summary','Define the target segment, ICP, buyer context, competitive frame, differentiated value and evidence before selecting messages or channels.','professional_rules',jsonb_build_array('Separate ICP from broad persona descriptions','Position around a meaningful customer problem and differentiated value','Support claims with evidence rather than adjectives')),
 jsonb_build_object('topic','Messaging and funnel','summary','Translate positioning into audience-specific value propositions, message hierarchy and a measurable journey from awareness through retention.','professional_rules',jsonb_build_array('Align message to lifecycle stage','Define one primary conversion objective per asset or step','Track handoffs and leakage between funnel stages')),
 jsonb_build_object('topic','Acquisition and experimentation','summary','Select channels based on audience, economics and intent; run controlled tests with explicit hypotheses and success criteria.','professional_rules',jsonb_build_array('Define hypothesis before launch','Change limited variables when causal learning matters','Use CAC and conversion with clear time window and denominator','Do not generalize platform behavior without current verification')),
 jsonb_build_object('topic','Measurement and attribution','summary','Use KPI trees linking business outcomes to leading indicators; treat attribution as a model with limitations rather than objective truth.','professional_rules',jsonb_build_array('Define metric formulas','Distinguish acquisition, activation, retention and revenue metrics','State attribution assumptions and data gaps'))),
 array['positioning','segmentation','ICP','personas','value-proposition','messaging','funnel','lifecycle','CAC','LTV','conversion','retention','experimentation','attribution'],array['campaign-planning','experiment-design','funnel-analysis','campaign-qa'],
