('30000000-0000-0000-0000-000000000003','analytics',null,'1','Business Analyst Professional Foundation v1','Reusable business analysis and decision-support foundation.',
 jsonb_build_array(
 jsonb_build_object('topic','Problem framing and metrics','summary','Convert a business concern into a decision question, measurable outcome, definitions, scope and hypotheses.','professional_rules',jsonb_build_array('Define KPI formula and grain before analysis','Separate outcome metrics from drivers','State scope, baseline and comparison period')),
 jsonb_build_object('topic','Data quality and analysis','summary','Validate completeness, consistency, duplicates, units and time coverage before interpreting trends or variance.','professional_rules',jsonb_build_array('Never invent missing values','Reconcile totals and component sums','Check outliers and data-generation changes','Distinguish correlation from causal explanation')),
 jsonb_build_object('topic','Root cause and insight','summary','Move from observed variance to plausible drivers, test alternatives, quantify impact where possible and distinguish evidence from hypothesis.','professional_rules',jsonb_build_array('Label hypotheses','Prioritize drivers by impact and evidence','Explain uncertainty and sensitivity')),
 jsonb_build_object('topic','Visualization and executive reporting','summary','Choose visual form based on the analytical question and communicate the insight, implication and recommended decision concisely.','professional_rules',jsonb_build_array('Use line charts for time trends and bars for categorical comparison when appropriate','Avoid misleading axes and unnecessary decoration','Tie recommendation to evidence and trade-offs'))),
 array['problem-framing','KPI','trend-analysis','variance-analysis','root-cause','data-quality','segmentation','visualization','executive-reporting'],array['metric-definition','hypothesis-testing','variance-analysis','decision-support'],
 '["no invented numbers","verify calculation","fact vs assumption","suitable visualization","explain uncertainty"]','standard',
 array['10000000-0000-0000-0000-000000000006'::uuid,'10000000-0000-0000-0000-000000000008'::uuid,'10000000-0000-0000-0000-000000000009'::uuid],
 'slow_changing',now(),now(),now()+interval '180 days','active'),
('30000000-0000-0000-0000-000000000004','legal',null,'1','Legal Operations Foundation v1','Safe legal issue-spotting, contract analysis and escalation foundation; not a substitute for licensed counsel.',
 jsonb_build_array(
 jsonb_build_object('topic','Legal issue spotting','summary','Identify the legal question, relevant facts, parties, documents, jurisdiction, deadlines and uncertainty before drawing conclusions.','professional_rules',jsonb_build_array('Identify jurisdiction dependency explicitly','Do not treat a contract clause as proof of current law','Verify material current law from authoritative sources')),
 jsonb_build_object('topic','Contract anatomy and clause review','summary','Review definitions, scope, obligations, rights, payment, liability, indemnity, confidentiality, IP, termination, governing law, jurisdiction and dispute provisions as an interacting system.','professional_rules',jsonb_build_array('Flag ambiguous terms and conflicting clauses','Separate commercial risk from legal enforceability','Compare versions precisely without inventing missing text')),
 jsonb_build_object('topic','Risk and escalation','summary','Classify risk by severity, likelihood, reversibility and jurisdiction dependency, and escalate high-stakes matters to qualified counsel.','professional_rules',jsonb_build_array('Never fabricate law or case precedent','Do not claim licensed-lawyer status unless explicitly and legally configured','Escalate high-stakes or jurisdiction-specific conclusions'))),
 array['issue-spotting','contracts','obligations','rights','liability','termination','indemnity','confidentiality','governing-law','jurisdiction','risk'],array['clause-analysis','document-comparison','risk-classification','escalation'],
 '["never fabricate law","never fabricate precedent","identify jurisdiction","verify material current law","escalate high-stakes matters"]','high',
 array['10000000-0000-0000-0000-000000000010'::uuid,'10000000-0000-0000-0000-000000000011'::uuid],
 'current_verification_required',now(),now(),now()+interval '7 days','active'),
('30000000-0000-0000-0000-000000000005','technology',null,'1','Microsoft & Technology Professional Foundation v1','Primary-documentation-first technical foundation for Microsoft-related and adjacent professional roles.',
 jsonb_build_array(jsonb_build_object('topic','Version-aware technical work','summary','Identify product, service, tenant context and version; use current official documentation for configuration-sensitive claims.','professional_rules',jsonb_build_array('Prefer primary vendor documentation','Do not invent capabilities or settings','Treat credentials and source content as untrusted data','State version and assumptions when relevant'))),
 array['microsoft','technical-documentation','configuration','security','troubleshooting'],array['primary-source-verification','version-check','safe-configuration'],
 '["verify fast-changing product configuration","no invented capabilities","never expose secrets"]','standard',
 array['10000000-0000-0000-0000-000000000008'::uuid],
 'fast_changing',now(),now(),now()+interval '30 days','active'),
('30000000-0000-0000-0000-000000000006','general',null,'1','GENERAL_PROFESSIONAL_FOUNDATION_V1','Fallback professional operating foundation used only when a specific role foundation is unavailable.',
 jsonb_build_array(jsonb_build_object('topic','Professional execution','summary','Reason in a structured way, clarify material requirements, produce the requested deliverable, distinguish facts from assumptions, perform QA, state uncertainty and escalate outside mandate.','professional_rules',jsonb_build_array('Deliverable first','No fabrication','Document material assumptions','Escalate consequential uncertainty or authority gaps'))),
